'use strict';

const fs = require('fs/promises');
const os = require('os');
const path = require('path');
const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  createInputFromAutoDetect
} = require('..');

const execFileAsync = promisify(execFile);

function parseArgs(argv) {
  const options = {
    seconds: Number(process.env.CLICK_COUNTDOWN_SECONDS || 5),
    portPath: process.env.THIFLOW_ROBOT_PORT || process.env.NANOKVM_PORT || process.env.CH9329_PORT || '',
    kind: process.env.THIFLOW_ROBOT_KIND || '',
    button: process.env.CLICK_COUNTDOWN_BUTTON || 'left',
    holdMs: Number(process.env.CLICK_COUNTDOWN_HOLD_MS || 80),
    repeat: Number(process.env.CLICK_COUNTDOWN_REPEAT || 1),
    intervalMs: Number(process.env.CLICK_COUNTDOWN_INTERVAL_MS || 120),
    nudgePx: Number(process.env.CLICK_COUNTDOWN_NUDGE_PX || 0),
    logDir: process.env.CLICK_COUNTDOWN_LOG_DIR || path.join(os.tmpdir(), 'thiflow-robot-click-tests')
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];

    if ((arg === '--seconds' || arg === '-s') && next) {
      options.seconds = Number(next);
      index += 1;
    } else if (arg === '--port' && next) {
      options.portPath = next;
      index += 1;
    } else if (arg === '--kind' && next) {
      options.kind = next;
      index += 1;
    } else if (arg === '--button' && next) {
      options.button = next;
      index += 1;
    } else if (arg === '--hold-ms' && next) {
      options.holdMs = Number(next);
      index += 1;
    } else if (arg === '--repeat' && next) {
      options.repeat = Number(next);
      index += 1;
    } else if (arg === '--interval-ms' && next) {
      options.intervalMs = Number(next);
      index += 1;
    } else if (arg === '--nudge-px' && next) {
      options.nudgePx = Number(next);
      index += 1;
    } else if (arg === '--log-dir' && next) {
      options.logDir = next;
      index += 1;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  if (!Number.isFinite(options.seconds) || options.seconds < 0) {
    throw new Error('--seconds must be a non-negative number');
  }

  if (options.kind && !['nanokvm', 'ch9329'].includes(options.kind)) {
    throw new Error('--kind must be nanokvm or ch9329');
  }

  if (!['left', 'right', 'middle'].includes(options.button)) {
    throw new Error('--button must be left, right, or middle');
  }

  if (!Number.isFinite(options.holdMs) || options.holdMs < 0) {
    throw new Error('--hold-ms must be a non-negative number');
  }

  if (!Number.isFinite(options.repeat) || options.repeat < 1) {
    throw new Error('--repeat must be a positive number');
  }

  if (!Number.isFinite(options.intervalMs) || options.intervalMs < 0) {
    throw new Error('--interval-ms must be a non-negative number');
  }

  if (!Number.isFinite(options.nudgePx)) {
    throw new Error('--nudge-px must be a number');
  }

  options.holdMs = Math.round(options.holdMs);
  options.repeat = Math.round(options.repeat);
  options.intervalMs = Math.round(options.intervalMs);
  options.nudgePx = Math.max(-127, Math.min(127, Math.round(options.nudgePx)));

  return options;
}

function printHelp() {
  console.log([
    'Usage: node demos/click-countdown.js [--seconds 5] [--port /dev/tty.usbserial-0001] [--kind nanokvm|ch9329]',
    '       [--button left|right|middle] [--hold-ms 300] [--repeat 5] [--interval-ms 150] [--nudge-px 1]',
    '',
    'Environment:',
    '  THIFLOW_ROBOT_PORT or NANOKVM_PORT or CH9329_PORT',
    '  THIFLOW_ROBOT_KIND=nanokvm|ch9329',
    '  CLICK_COUNTDOWN_SECONDS=5',
    '  CLICK_COUNTDOWN_BUTTON=left',
    '  CLICK_COUNTDOWN_HOLD_MS=80',
    '  CLICK_COUNTDOWN_REPEAT=1',
    '  CLICK_COUNTDOWN_INTERVAL_MS=120',
    '  CLICK_COUNTDOWN_NUDGE_PX=0',
    '  CLICK_COUNTDOWN_LOG_DIR=/tmp/thiflow-robot-click-tests'
  ].join('\n'));
}

function formatLocalDate(date) {
  return new Intl.DateTimeFormat('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZoneName: 'short'
  }).format(date);
}

function buttonMask(button) {
  if (button === 'right') return 0x02;
  if (button === 'middle') return 0x04;
  return 0x01;
}

async function getMacCursorPos() {
  if (process.platform !== 'darwin') {
    return null;
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let p = NSEvent.mouseLocation',
      'let screens = NSScreen.screens',
      'let screen = screens.first(where: { NSMouseInRect(p, $0.frame, false) }) ?? screens.first',
      'if let s = screen {',
      '  let f = s.frame',
      '  let x = Int(p.x - f.minX)',
      '  let y = Int(f.maxY - p.y)',
      '  print("\\(x),\\(y),\\(Int(f.width)),\\(Int(f.height))")',
      '} else {',
      '  print("0,0,1,1")',
      '}'
    ].join('\n')
  ]);
  const [x, y, width, height] = stdout.trim().split(',').map((value) => Number(value));
  if ([x, y, width, height].every((value) => Number.isFinite(value))) {
    return { x, y, width, height };
  }
  return null;
}

async function clickCh9329AbsoluteCurrent(input, point, options) {
  if (!point || !input?._debug?.sendAbsoluteMove) {
    return false;
  }

  const mask = buttonMask(options.button);
  for (let index = 0; index < options.repeat; index += 1) {
    await input._debug.sendAbsoluteMove(point.x, point.y, mask, 0, point.width, point.height);
    await sleep(options.holdMs);
    await input._debug.sendAbsoluteMove(point.x, point.y, 0, 0, point.width, point.height);
    if (index < options.repeat - 1) {
      await sleep(options.intervalMs);
    }
  }
  await sleep(options.intervalMs);
  return true;
}

async function appendRunLog(logDir, record) {
  await fs.mkdir(logDir, { recursive: true });
  const logPath = path.join(logDir, 'click-countdown.jsonl');
  await fs.appendFile(logPath, `${JSON.stringify(record)}\n`, 'utf8');
  return logPath;
}

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function countdown(seconds) {
  const wholeSeconds = Math.floor(seconds);
  for (let remaining = wholeSeconds; remaining > 0; remaining -= 1) {
    console.log(`[click-countdown] ${remaining}s 后左键点击，请把鼠标挪到目标位置...`);
    await sleep(1000);
  }

  const extraMs = Math.round((seconds - wholeSeconds) * 1000);
  if (extraMs > 0) {
    await sleep(extraMs);
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    printHelp();
    return;
  }

  const startedAt = new Date();
  const detectOptions = {
    portPath: options.portPath || undefined,
    kind: options.kind || undefined
  };

  console.log(`[click-countdown] 日期: ${formatLocalDate(startedAt)} (${startedAt.toISOString()})`);
  console.log('[click-countdown] 正在探测并连接输入设备...');

  const { detection, input } = await createInputFromAutoDetect(detectOptions);
  await input.connect();
  console.log(`[click-countdown] 已连接: ${detection.kind || 'unknown'} ${detection.portPath}`);

  const record = {
    event: 'click-countdown',
    startedAt: startedAt.toISOString(),
    startedAtLocal: formatLocalDate(startedAt),
    platform: process.platform,
    detection: {
      kind: detection.kind,
      portPath: detection.portPath,
      baudRate: detection.baudRate
    },
    seconds: options.seconds,
    button: options.button,
    holdMs: options.holdMs,
    repeat: options.repeat,
    intervalMs: options.intervalMs,
    nudgePx: options.nudgePx
  };

  try {
    await countdown(options.seconds);
    record.cursorBeforeClick = await getMacCursorPos();
    record.clickedAt = new Date().toISOString();
    record.clickedAtLocal = formatLocalDate(new Date(record.clickedAt));

    if (detection.kind === 'ch9329' && process.platform === 'darwin') {
      record.clickTransport = 'ch9329-absolute-current';
      const absoluteClicked = await clickCh9329AbsoluteCurrent(input, record.cursorBeforeClick, options);
      if (!absoluteClicked) {
        record.clickTransport = 'relative';
        await input.click(options.button, {
          holdMs: options.holdMs,
          repeat: options.repeat,
          intervalMs: options.intervalMs,
          nudgePx: options.nudgePx
        });
      }
    } else {
      record.clickTransport = 'relative';
      await input.click(options.button, {
        holdMs: options.holdMs,
        repeat: options.repeat,
        intervalMs: options.intervalMs,
        nudgePx: options.nudgePx
      });
    }
    record.ok = true;
    console.log(`[click-countdown] ${options.button} 点击完成，位置: ${JSON.stringify(record.cursorBeforeClick)}`);
  } catch (error) {
    record.ok = false;
    record.error = error?.message || String(error);
    throw error;
  } finally {
    await input.disconnect().catch(() => {});
    const logPath = await appendRunLog(options.logDir, record);
    console.log(`[click-countdown] 运行记录已写入: ${logPath}`);
  }
}

main().catch((error) => {
  console.error('[click-countdown] failed:', error);
  process.exitCode = 1;
});
